(function(E){ const x = E["ai-m3"] = E["ai-m3"] || {units:{}}; x.units["ai-12"] = {"grammar":{"id":"c-ai-12-g","level":"B1","course":"ai-internet","unit":"ai-12","title":"Saying how sure you are","titleTr":"Ne kadar emin olduğunu söylemek","titleFa":"بگو چقدر مطمئنی","formsTable":{"headers":{"en":["How sure","Pattern","Example"],"tr":["Ne kadar emin","Kalıp","Örnek"],"fa":["چقدر مطمئن","الگو","مثال"]},"rows":[["sure","I found this in","I found this in the datasheet."],["partly","It seems that","It seems that the price went up."],["not sure","I could not confirm","I could not confirm the date."]]},"wrong":"According the AI answer, it lasts two years.","right":"According to the AI answer, it lasts two years.","blank":{"sentence":"___ to the answer, the law changed in May.","word":"According","distractors":["Accord","Following of"]},"wrong2":"I could not to confirm it.","right2":"I could not confirm it.","blank2":{"sentence":"I could not ___ the second claim.","word":"confirm","distractors":["to confirm","confirming"]},"expParts":{"tryFrom":"blank","rule":[{"en":"According to + source gives the source, not your view.","tr":"According to + kaynak, görüşünü değil kaynağı söyler.","fa":"با according to نام منبع را می‌گویی، نه نظر خودت را.","ex":"According to the AI answer, it lasts two years."},{"en":"As far as I can tell shows your limit.","tr":"As far as I can tell sınırını gösterir.","fa":"با As far as I can tell نشان می‌دهی تا کجا مطمئنی.","ex":"As far as I can tell, it is correct."}],"test":{"en":"Did you say where you found it?","tr":"Nerede bulduğunu söyledin mi?","fa":"گفته‌ای کجا پیدایش کردی؟"}},"errorWatch":[{"find":["according the"],"fix":{"en":"Say \"according to\".","tr":"\"according to\" de.","fa":"بگو «according to»."}}]},"b2":{"id":"c-ai-12-b2","level":"B2","course":"ai-internet","unit":"ai-12","track":"B2","title":"Careful verbs: appears to, is said to, there is no evidence that","titleTr":"Dikkatli fiiller: appears to, is said to, there is no evidence that","titleFa":"فعل‌های محتاطانه: appears to، is said to، there is no evidence that","formsTable":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["appears to + verb","This study appears to be invented."],["there is no evidence that","There is no evidence that it lasts longer."]]},"wrong":"This study appears being invented.","right":"This study appears to be invented.","blank":{"sentence":"The source appears ___ be a seller's blog.","word":"to","distractors":["for","of"]},"wrong2":"There is no evidence for that it works.","right2":"There is no evidence that it works.","blank2":{"sentence":"There is no evidence ___ it saves money.","word":"that","distractors":["for that","of that"]},"expParts":{"tryFrom":"blank","rule":[{"en":"Appears to is careful: it may not be true.","tr":"appears to dikkatli bir ifadedir: doğru olmayabilir.","fa":"با appears to محتاطانه حرف می‌زنی، چون شاید درست نباشد.","ex":"The page appears to be old."},{"en":"There is no evidence that means you looked and found none.","tr":"there is no evidence that, bakıp bulamadığını söyler.","fa":"there is no evidence that یعنی گشتی و پیدا نکردی.","ex":"There is no evidence that this is true."}],"test":{"en":"Did you look? Then you can say no evidence.","tr":"Baktın mı? O zaman no evidence diyebilirsin.","fa":"اگر گشته‌ای، می‌توانی بگویی no evidence."}},"errorWatch":[{"find":["no evidence for that"],"fix":{"en":"Say \"no evidence that\".","tr":"\"no evidence that\" de.","fa":"بگو «no evidence that»."}}],"useIn":{"en":"B2: write your note with appears to and there is no evidence that.","tr":"B2: Notunu appears to ve there is no evidence that ile yaz.","fa":"B2: یادداشتت را با appears to و there is no evidence that بنویس."},"exitItem":{"from":"ai-12","kind":"blank","prompt":"This link appears ___ be broken.","options":["to","for","of"],"correct":0,"why":{"en":"to: 'appears to be' is a careful way to report what you see. 'Appears for' and 'appears of' are not English.","tr":"to: 'appears to be' gördüğünü dikkatlice aktarmanın yoludur. 'Appears for' ve 'appears of' İngilizce değildir.","fa":"to درست است، چون appears to be شیوه‌ی محتاطانه‌ی گفتن چیزی است که می‌بینی. appears for و appears of انگلیسی نیستند."},"hint2":{"en":"appears works like seems here: it needs a small word before the next verb, be. Which one?","tr":"appears burada seems gibi çalışır: sonraki fiilden (be) önce küçük bir kelime ister. Hangisi?","fa":"⁨appears⁩ اینجا مثل ⁨seems⁩ است: قبل از فعل بعدی، یعنی ⁨be⁩، یک کلمه‌ی کوچک لازم دارد. کدام؟"}}},"vocab":{"id":"c-ai-12-v","level":"B1","category":"vocab","course":"ai-internet","unit":"ai-12","goals":["career"],"title":{"en":"Checking sources","tr":"Kaynak kontrolü","fa":"بررسی منبع‌ها"},"cards":[{"word":"Citation","sentence":"Each citation is a numbered link.","meaning":{"en":"A numbered link to a source","tr":"Bir kaynağa giden numaralı bağlantı","fa":"لینک شماره‌دار به یک منبع"}},{"word":"Follow-up","sentence":"Write a follow-up on the same topic.","meaning":{"en":"Your next question, on the same topic","tr":"Aynı konudaki bir sonraki sorun","fa":"سؤال بعدی‌ات درباره‌ی همان موضوع"}},{"word":"Deep Research","sentence":"Deep Research writes a longer report.","meaning":{"en":"Runs many searches and writes a longer report, in a few minutes","tr":"Birçok arama yapar ve birkaç dakikada daha uzun bir rapor yazar","fa":"جست‌وجوهای زیادی انجام می‌دهد و در چند دقیقه گزارش طولانی‌تری می‌نویسد"}},{"word":"invented","sentence":"This study looks invented.","meaning":{"en":"Made up, not real.","tr":"Uydurma, gerçek olmayan.","fa":"ساختگی، نه واقعی."}},{"word":"confirm","sentence":"I could not confirm the number.","meaning":{"en":"To show that something is true.","tr":"Bir şeyin doğru olduğunu göstermek.","fa":"نشان دادن اینکه چیزی درست است."}}]},"judge":{"id":"c-ai-12-j","course":"ai-internet","unit":"ai-12","type":"judge","title":{"en":"What can you say about this claim?","tr":"Bu iddia için ne diyebilirsin?","fa":"درباره‌ی این ادعا چه می‌توانی بگویی؟"},"prompt":"You opened each link. Choose what you can say.","parts":["Confirmed","Partly confirmed","Could not confirm"],"instruction":{"en":"Choose one result for each claim.","tr":"Her iddia için bir sonuç seç.","fa":"برای هر ادعا یک نتیجه انتخاب کن."},"mode":"single","screen":{"id":"scr-perplexity-1","src":"courses/ai-internet/assets/scr-perplexity-1.webp?v=46b906935a","alt":"Our drawing of an AI search screen like Perplexity, November 2026, not a screenshot. A question box, an answer with the numbers 1 and 2, and a side list of two source pages."},"items":[{"by":"Example check","answer":"Claim: the standard was updated in 2024. The standards body's own page says 2024.","present":["Confirmed"],"fix":{"en":"The right page says the same.","tr":"Doğru sayfa aynısını söylüyor.","fa":"صفحه‌ی درست همین را می‌گوید."}},{"by":"Example check","answer":"Claim: the lamps last 50,000 hours. The maker's page says \"up to 50,000 hours\".","present":["Partly confirmed"],"fix":{"en":"Up to means at most, and maybe less.","tr":"Up to en fazla demektir, daha az olabilir.","fa":"up to یعنی حداکثر و شاید کمتر."}},{"by":"Example check","answer":"Claim: a 2024 study proves it. The link fails and the title is nowhere.","present":["Could not confirm"],"fix":{"en":"It may be invented. Don't use it.","tr":"Uydurma olabilir. Kullanma.","fa":"شاید ساختگی باشد. از آن استفاده نکن."}},{"by":"Example check","answer":"Claim: 80 of 100 firms use it. The page is about a different product.","present":["Could not confirm"],"fix":{"en":"The page doesn't say that.","tr":"Sayfa bunu söylemiyor.","fa":"صفحه این را نمی‌گوید."}}]},"speaking":{"id":"ai-12","course":"ai-internet","unit":"ai-12","topic":{"en":"Say how sure you are","tr":"Ne kadar emin olduğunu söyle","fa":"بگو چقدر مطمئنی"},"warmup":{"en":"What is something at work that everybody says, but you never checked?","tr":"İşte herkesin söylediği ama senin hiç kontrol etmediğin bir şey ne?","fa":"در کارت چه چیزی هست که همه می‌گویند، ولی تو هیچ‌وقت بررسی‌اش نکرده‌ای؟"},"questions":[{"en":"Your manager asks: \"Is this number right?\" Say what you found, and what you could not confirm.","tr":"Yöneticin soruyor: \"Is this number right?\" Ne bulduğunu ve neyi doğrulayamadığını söyle.","fa":"مدیرت می‌پرسد: «Is this number right?» بگو چه پیدا کردی و چه چیزی را نتوانستی تأیید کنی."},{"en":"A colleague says: \"It has links, so it must be true.\" Reply.","tr":"Bir meslektaşın diyor ki: \"It has links, so it must be true.\" Yanıtla.","fa":"همکارت می‌گوید: «It has links, so it must be true.» جواب بده."},{"en":"You opened a link and the page doesn't say what the answer says. Say what you do next.","tr":"Bir bağlantıyı açtın ve sayfa yanıtın söylediğini söylemiyor. Sonra ne yapacağını söyle.","fa":"لینکی را باز کردی، ولی صفحه همان چیزی را که جواب گفته نمی‌گوید. بگو بعدش چه می‌کنی."}],"followups":[{"en":"Now say it again about your own work. Use made-up names and numbers.","tr":"Şimdi aynısını kendi işin için söyle. Uydurma ad ve sayılar kullan.","fa":"حالا همین را درباره‌ی کار خودت بگو. از نام‌ها و عددهای ساختگی استفاده کن."}],"expressions":[{"phrase":"As far as I can tell...","meaning":{"en":"Shows your limit.","tr":"Sınırını gösterir.","fa":"نشان می‌دهد تا کجا مطمئنی."}},{"phrase":"I could not confirm...","meaning":{"en":"Says what is still open.","tr":"Hâlâ açık olanı söyler.","fa":"می‌گوید چه چیزی هنوز معلوم نیست."}}],"model":"As far as I can tell, the date is right. I found it on the maker's own page. The number is different. According to the AI answer, the lamps last thirty-seven thousand hours, but the page says up to fifty thousand. I could not confirm the study, because the link fails. So I would not use that number in the report.","selfCheck":[{"en":"I did every point of the task.","tr":"Görevin her noktasını yaptım.","fa":"همه‌ی نکته‌های تمرین را انجام دادم."},{"en":"I used at least two phrases from this lesson.","tr":"Bu dersten en az iki ifade kullandım.","fa":"دست‌کم دو عبارت از این درس به کار بردم."},{"en":"I spoke in short, clear sentences.","tr":"Kısa ve net cümlelerle konuştum.","fa":"با جمله‌های کوتاه و روشن حرف زدم."},{"en":"I said how sure I was.","tr":"Ne kadar emin olduğumu söyledim.","fa":"گفتم چقدر مطمئنم."}]},"writing":{"id":"c-ai-12-w","title":{"en":"Write a note on what you confirmed","tr":"Neyi doğruladığına dair not yaz","fa":"یادداشتی درباره‌ی چیزهای تأییدشده بنویس"},"course":"ai-internet","unit":"ai-12","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":null,"prompt":{"en":"An AI answer says the Nova 20 printer was launched in 2015, and that a 2023 study shows it saves money. You found the date on the maker's page. You can't find the study. Write your note.","tr":"Bir yapay zekâ yanıtı, Nova 20 yazıcının 2015'te çıktığını ve 2023 tarihli bir çalışmanın para kazandırdığını gösterdiğini söylüyor. Tarihi üreticinin sayfasında buldun. Çalışmayı bulamıyorsun. Notunu yaz.","fa":"یک جواب هوش مصنوعی می‌گوید چاپگر Nova 20 در ۲۰۱۵ عرضه شده و تحقیقی از ۲۰۲۳ نشان می‌دهد در هزینه صرفه‌جویی می‌کند. تاریخ را در صفحه‌ی سازنده پیدا کردی، ولی تحقیق را پیدا نمی‌کنی. یادداشتت را بنویس."},"model":"According to the AI answer, the Nova 20 printer was launched in 2015, and a 2023 study shows it saves money. I found the date on the maker's page. I could not confirm the study, because the title is not in any search. So I will not use that claim.","frame":"According to the AI answer, ___. I found ___ on ___. I could not confirm ___, because ___. So I will ___.","words":[{"word":"According to"},{"word":"I could not confirm"}],"minWords":30,"minSentences":2,"rubric":["Task done: every point of the task is there","Organised: clear parts, in a sensible order","Language: the phrases of this lesson, used correctly","Tone: clear and honest; nothing you cannot explain"],"rubricI18n":{"tr":["Görev: görevin her noktası var","Düzen: açık bölümler, mantıklı sıra","Dil: bu dersin ifadeleri, doğru kullanılmış","Üslup: açık ve dürüst; açıklayamayacağın bir şey yok"],"fa":["کامل بودن کار: همه‌ی نکته‌های تمرین آمده","نظم: بخش‌های روشن، با ترتیب منطقی","زبان: عبارت‌های این درس، درست به کار رفته","لحن: روشن و صادق؛ چیزی که نتوانی توضیح بدهی در آن نیست"]},"b2Task":{"en":"B2 track: no frame. Use appears to and there is no evidence that.","tr":"B2 yolu: hazır çerçeve yok. appears to ve there is no evidence that kullan.","fa":"مسیر B2: چارچوب آماده نداری. از appears to و there is no evidence that استفاده کن."},"own":{"en":"Now check one claim you heard at work. Write the same kind of note.","tr":"Şimdi işte duyduğun bir iddiayı kontrol et. Aynı türden not yaz.","fa":"حالا ادعایی را که در کار شنیده‌ای بررسی کن و همین نوع یادداشت را بنویس."},"routes":[{"t":{"en":"I use an AI tool","tr":"Bir yapay zekâ aracı kullanıyorum","fa":"از یک ابزار هوش مصنوعی استفاده می‌کنم"},"s":{"en":"Ask an AI search tool a work question. Open two of its links and write your note.","tr":"Yapay zekâlı arama aracına işle ilgili bir soru sor. İki bağlantısını aç ve notunu yaz.","fa":"یک سؤال کاری از ابزار جست‌وجوی هوش مصنوعی بپرس. دو لینکش را باز کن و یادداشتت را بنویس."}},{"t":{"en":"I don't have a tool","tr":"Bir aracım yok","fa":"ابزاری ندارم"},"s":{"en":"Use the example answer and claims in this lesson. The note is the same.","tr":"Bu dersteki örnek yanıtı ve iddiaları kullan. Not aynı.","fa":"از جواب و ادعاهای نمونه‌ی همین درس استفاده کن. یادداشتت فرقی نمی‌کند."},"noTool":true}],"parts":[{"t":{"en":"What the AI answer says: According to ...","tr":"Yapay zekâ yanıtının söylediği: According to ...","fa":"آنچه جواب هوش مصنوعی می‌گوید: ⁨According to ...⁩"},"find":["according to"],"sample":"according to the AI answer: launched in 2015 · a 2023 study"},{"t":{"en":"What you found, and where","tr":"Neyi, nerede bulduğun","fa":"چه چیزی را کجا پیدا کردی"},"find":["i found","i checked","on the maker's page"],"sample":"I found the date on the maker's page"},{"t":{"en":"What you could not confirm, and why","tr":"Neyi doğrulayamadığın ve nedeni","fa":"چه چیزی را نتوانستی تأیید کنی و چرا"},"find":["i could not confirm","i couldn't confirm","could not find","not in any search"],"sample":"I could not confirm the study: the title is not in any search"},{"t":{"en":"What you will do with the claim","tr":"İddiayla ne yapacağın","fa":"با آن ادعا چه می‌کنی"},"find":["so i will","i will not use","i won't use","i will use"],"sample":"so I will not use that claim"}]},"exit":{"id":"c-ai-12-x","course":"ai-internet","unit":"ai-12","type":"exit","items":[{"from":"ai-12","kind":"mcq","prompt":"What does Perplexity give with its answer?","options":["Numbered links to sources","A list of paid plans","A phone number for help"],"correct":0,"why":{"en":"Numbered links to sources: you can open each one and check it. A list of paid plans is on its website, not in its answers.","tr":"Numbered links to sources: her birini açıp kontrol edebilirsin. Ücretli planların listesi cevaplarında değil, web sitesindedir.","fa":"Numbered links to sources درست است، چون می‌توانی هر کدام را باز و بررسی کنی. فهرست نسخه‌های پولی در سایتش است، نه در جواب‌هایش."},"point":1},{"from":"ai-12","kind":"mcq","prompt":"Which is a warning sign?","options":["An exact number with no source","A link that opens on a real page","A page that shows its date"],"correct":0,"why":{"en":"An exact number with no source: exact numbers look trustworthy, but with no source they may be invented. A page that shows its date is a good sign, not a warning.","tr":"An exact number with no source: kesin sayılar güvenilir görünür ama kaynağı yoksa uydurulmuş olabilir. Tarihini gösteren bir sayfa uyarı değil, iyi bir işarettir.","fa":"An exact number with no source درست است، چون عدد دقیق قابل اعتماد به چشم می‌آید، ولی بدون منبع شاید ساختگی باشد. صفحه‌ای که تاریخش را نشان می‌دهد نشانه‌ی خوبی است، نه هشدار."},"point":4},{"from":"ai-12","kind":"blank","prompt":"I could not ___ the study.","options":["confirming","confirm","to confirm"],"correct":1,"why":{"en":"confirm: after could not, use the base verb. 'To confirm' adds to, which could never takes, and 'confirming' is the -ing form.","tr":"confirm: could not'tan sonra yalın fiil gelir. 'To confirm' could'un asla almadığı to'yu ekler; 'confirming' ise -ing biçimidir.","fa":"confirm درست است، چون بعد از could not فعل ساده می‌آید. to confirm یک to دارد که could هیچ‌وقت با آن نمی‌آید و confirming شکل ing است."},"point":6,"hint2":{"en":"After could not, which form of the verb comes: with to, with -ing, or the verb on its own?","tr":"could not ifadesinden sonra fiil hangi biçimde gelir: to ile mi, -ing ile mi, yoksa yalın hâliyle mi?","fa":"بعد از ⁨could not⁩ فعل به چه شکلی می‌آید: با ⁨to⁩، با ⁨-ing⁩ یا خودِ فعل به‌تنهایی؟"}},{"from":"ai-11","kind":"mcq","prompt":"You used AI. Which note is honest?","options":["I wrote all of this myself, with no help from any tool.","AI wrote this, so the facts should all be right.","I used AI to draft this, then I checked the dates."],"correct":2,"why":{"en":"I used AI to draft this, then I checked the dates: it says what AI did and what you did. 'AI wrote this, so the facts should all be right' puts trust in the tool, not in a check.","tr":"I used AI to draft this, then I checked the dates: yapay zekânın ne yaptığını ve senin ne yaptığını söyler. 'AI wrote this, so the facts should all be right' güveni kontrole değil, araca verir.","fa":"I used AI to draft this, then I checked the dates درست است، چون می‌گوید هوش مصنوعی چه کرد و خودت چه کردی. جمله‌ی AI wrote this, so the facts should all be right به ابزار اعتماد می‌کند، نه به بررسی."},"point":2},{"from":"ai-9","kind":"mcq","prompt":"Which line belongs in a brief?","options":["Stop before anything is sent.","Do your best work on this job.","Please be careful with all of it."],"correct":0,"why":{"en":"Stop before anything is sent: it is a clear stop point the tool can follow. 'Do your best work' sounds encouraging, but it gives the tool nothing to do or check.","tr":"Stop before anything is sent: aracın uyabileceği net bir durma noktasıdır. 'Do your best work' cesaret verici görünür ama araca yapacak ya da kontrol edecek bir şey vermez.","fa":"Stop before anything is sent درست است، چون نقطه‌ی توقف روشنی است که ابزار می‌تواند رعایتش کند. Do your best work دلگرم‌کننده است، ولی هیچ کار یا معیاری به ابزار نمی‌دهد."},"point":1,"hint2":{"en":"A line in a brief is one the tool can follow and you can check. Which option is like that?","tr":"Brief'teki bir satır, aracın uygulayabileceği ve senin kontrol edebileceğin bir satırdır. Hangi seçenek böyle?","fa":"خطی که در شرح کار می‌آید باید چیزی باشد که ابزار بتواند اجرایش کند و تو بتوانی بررسی‌اش کنی. کدام گزینه این‌طور است؟"}},{"from":"ai-5","kind":"blank","prompt":"___ only on this page, list the dates.","options":["Basing","Based","Base"],"correct":1,"why":{"en":"Based: the fixed phrase is 'based only on'. 'Basing' is a different form, and 'Base' would turn it into an order to the reader.","tr":"Based: kalıp ifade 'based only on'dur. 'Basing' farklı bir biçimdir; 'Base' ise cümleyi okura verilen bir emre çevirir.","fa":"Based درست است، چون عبارت ثابت based only on است. basing شکل دیگری است و Base جمله را به یک دستور به خواننده تبدیل می‌کند."},"point":6,"hint2":{"en":"It is a fixed phrase for keeping the tool inside your text. Which form of the verb base does it use: plain, -ing or past participle?","tr":"Bu, aracı metninin içinde tutan sabit bir kalıp. base fiilinin hangi hâlini kullanır: yalın hâlini mi, -ing hâlini mi, üçüncü hâlini mi?","fa":"این عبارتی ثابت است تا ابزار داخل متن تو بماند. کدام شکل فعل ⁨base⁩ در آن می‌آید: شکل ساده، با ⁨-ing⁩ یا اسم مفعول؟"}}]},"explain":{"id":"c-ai-12-e","course":"ai-internet","unit":"ai-12","type":"explain","level":"B1","title":{"en":"Perplexity: is that really true?","tr":"Perplexity: bu gerçekten doğru mu?","fa":"⁨Perplexity⁩: واقعاً درست است؟"},"objective":{"en":"After this lesson, you can open an AI answer's sources, check its claims and write a note on what you confirmed.","tr":"Bu dersin sonunda bir yapay zekâ yanıtının kaynaklarını açabilecek, iddialarını kontrol edebilecek ve neyi doğruladığını not edebileceksin.","fa":"بعد از این درس می‌توانی منبع‌های جواب هوش مصنوعی را باز کنی، ادعاهایش را بررسی کنی و یادداشتی درباره‌ی چیزهای تأییدشده بنویسی."},"hook":{"en":"A search engine gives links. AI search gives an answer with links. It saves time, but the page may not say what the answer says.","tr":"Arama motoru bağlantı verir. Yapay zekâlı arama bağlantılı yanıt verir. Zaman kazandırır ama sayfa, yanıtın söylediğini söylemeyebilir.","fa":"موتور جست‌وجو لینک می‌دهد. جست‌وجوی هوش مصنوعی جواب همراه با لینک می‌دهد. این کار در وقتت صرفه‌جویی می‌کند، ولی شاید صفحه همان چیزی را نگوید که جواب گفته است."},"before":{"en":"An AI answer cites a 2023 study you can't find. Write your note on it.","tr":"Bir yapay zekâ yanıtı, bulamadığın 2023 tarihli bir çalışmayı kaynak gösteriyor. Bu konudaki notunu yaz.","fa":"یک جواب هوش مصنوعی به تحقیقی از سال ۲۰۲۳ استناد می‌کند که نمی‌توانی پیدایش کنی. یادداشتت را درباره‌اش بنویس."},"stats":[{"label":{"en":"Minutes","tr":"Dakika","fa":"دقیقه"},"value":"25"},{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"6"},{"label":{"en":"Tasks","tr":"Görev","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The tool","tr":"Araç","fa":"ابزار"},"head":{"en":"What Perplexity is","tr":"Perplexity nedir","fa":"⁨Perplexity⁩ چیست"},"body":{"en":"Perplexity is an AI search tool. You ask a question as you would ask a person.","tr":"Perplexity, yapay zekâlı bir arama aracıdır. Bir insana sorar gibi soru sorarsın.","fa":"⁨Perplexity⁩ یک ابزار جست‌وجوی هوش مصنوعی است. طوری سؤال می‌پرسی که انگار از یک آدم می‌پرسی."},"steps":[{"en":"It searches first and then writes, so the answer has numbered links you can open.","tr":"Önce arar, sonra yazar; bu yüzden yanıtta açabileceğin numaralı bağlantılar olur.","fa":"اول می‌گردد و بعد می‌نویسد، پس جوابش لینک‌های شماره‌داری دارد که می‌توانی بازشان کنی.","ex":"... last up to 50,000 hours [1]"},{"en":"It still writes likely words about those pages, so its sentence may differ from the page.","tr":"Yine de bu sayfalar hakkında olası kelimeler yazar; cümlesi sayfadakinden farklı olabilir.","fa":"باز هم درباره‌ی آن صفحه‌ها کلمه‌های محتمل می‌نویسد، پس ممکن است جمله‌اش با صفحه فرق داشته باشد.","ex":"Open [1]. Does it say that?"}],"tip":{"en":"As of October 2026. Tools change.","tr":"Ekim 2026 itibarıyla. Araçlar değişebilir.","fa":"به‌روز تا اکتبر ۲۰۲۶. ابزارها تغییر می‌کنند."}},{"eyebrow":{"en":"The tool","tr":"Araç","fa":"ابزار"},"head":{"en":"What it is good for, and not","tr":"Neye yarar, neye yaramaz","fa":"به چه کاری می‌آید و به چه کاری نه"},"steps":[{"en":"A quick overview, with links to start from","tr":"Başlangıç için bağlantılarla birlikte hızlı bir genel bakış","fa":"یک نگاه کلی سریع، با لینک‌هایی برای شروع","ex":"What changed in EU packaging rules this year?"},{"en":"Finding the right English words for a topic","tr":"Bir konunun doğru İngilizce kelimelerini bulmak","fa":"پیدا کردن کلمه‌های انگلیسی درست برای یک موضوع","ex":"What is the English term for this part?"},{"en":"Not the best: a final answer without opening the links. A link doesn't prove the answer.","tr":"En iyisi değil: Bağlantıları açmadan nihai yanıt almak. Bağlantı, yanıtı kanıtlamaz.","fa":"بهترین گزینه نیست: جواب نهایی بدون باز کردن لینک‌ها. لینک ثابت نمی‌کند که جواب درست است.","ex":"Open the link first."},{"en":"Not the best: writing a long email in your voice. A text assistant suits that better.","tr":"En iyisi değil: Kendi üslubunla uzun bir e-posta yazmak. Bunun için metin asistanı daha uygundur.","fa":"بهترین گزینه نیست: نوشتن ایمیل طولانی با لحن خودت. دستیار متنی برای این کار مناسب‌تر است.","ex":"Long email? Use a text assistant."}]},{"eyebrow":{"en":"The tool","tr":"Araç","fa":"ابزار"},"head":{"en":"How to start","tr":"Nasıl başlanır","fa":"چطور شروع کنی"},"steps":[{"en":"Go to perplexity.ai.","tr":"perplexity.ai adresine git.","fa":"به ⁨perplexity.ai⁩ برو."},{"en":"Type a question, as you would ask a person.","tr":"Bir insana sorar gibi sorunu yaz.","fa":"سؤالت را طوری بنویس که انگار از یک آدم می‌پرسی."},{"en":"Read the answer and press a number to see its source.","tr":"Yanıtı oku ve kaynağını görmek için bir numaraya bas.","fa":"جواب را بخوان و برای دیدن منبع روی یک شماره بزن."},{"en":"Open the page. Does it really say that?","tr":"Sayfayı aç. Gerçekten bunu mu söylüyor?","fa":"صفحه را باز کن. واقعاً همین را می‌گوید؟"}],"phrases":[{"phrase":"What is the usual lifespan of LED lamps in a hotel?\nUse the documents of manufacturers if you can.\nGive a short answer. After each claim, show which source supports it.","meaning":{"en":"It searches live, and each claim comes with a number you can open.","tr":"Canlı arama yapar ve her iddia, açabileceğin bir numarayla gelir.","fa":"زنده جست‌وجو می‌کند و هر ادعا با شماره‌ای می‌آید که می‌توانی بازش کنی."},"copy":true}],"tip":{"en":"No account, or it doesn't open? That's fine: the practice in this lesson uses fixed examples. More words and prompts are in this tool's guide.","tr":"Hesabın yok ya da açılmıyor mu? Sorun değil: Bu dersin uygulamasında sabit örnekler var. Diğer kelimeler ve prompt'lar bu aracın rehberinde.","fa":"حساب نداری یا باز نمی‌شود؟ اشکالی ندارد: تمرین‌های این درس نمونه‌های آماده دارند. کلمه‌ها و پرامپت‌های بیشتر در راهنمای این ابزار هستند."}},{"head":{"en":"Signs that a claim may be invented","tr":"Bir iddianın uydurma olabileceğinin işaretleri","fa":"این نشانه‌ها می‌گویند ادعا شاید ساختگی باشد"},"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"body":{"en":"Any AI tool can invent studies, links and quotes that look real, because it writes what a real source would look like (Lesson 1.1).","tr":"Her yapay zekâ aracı gerçek görünen çalışmalar, bağlantılar ve alıntılar uydurabilir, çünkü gerçek bir kaynağın neye benzeyeceğini yazar (Ders 1.1).","fa":"هر ابزار هوش مصنوعی ممکن است تحقیق، لینک و نقل‌قولی بسازد که واقعی به نظر بیاید، چون چیزی می‌نویسد که شبیه منبع واقعی است (درس ۱.۱)."},"steps":[{"en":"No link, or a link that fails.","tr":"Bağlantı yok ya da bağlantı açılmıyor.","fa":"لینک ندارد یا لینک باز نمی‌شود.","ex":"a study with no link"},{"en":"You can't find the title in a search.","tr":"Başlığı aramada bulamıyorsun.","fa":"عنوانش در جست‌وجو پیدا نمی‌شود.","ex":"\"The 2024 Hotel Lighting Report\""},{"en":"It gives an exact number with no source.","tr":"Kaynaksız kesin bir sayı veriyor.","fa":"عددی دقیق می‌دهد، ولی منبعی ندارد.","ex":"\"exactly 37,000 hours\""}]},{"head":{"en":"Three checks","tr":"Üç kontrol","fa":"سه بررسی"},"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"steps":[{"en":"Open the link, because a link that fails is a warning.","tr":"Bağlantıyı aç, çünkü açılmayan bağlantı bir uyarıdır.","fa":"لینک را باز کن، چون لینکی که باز نشود نشانه‌ی خطر است.","ex":"Does it open?"},{"en":"Search for the title, because an invented study can't be found.","tr":"Başlığı ara, çünkü uydurma bir çalışma bulunamaz.","fa":"عنوان را جست‌وجو کن، چون تحقیق ساختگی جایی پیدا نمی‌شود.","ex":"Does it exist?"},{"en":"Read the page, because even a real page may say something else.","tr":"Sayfayı oku, çünkü gerçek bir sayfa bile başka bir şey söylüyor olabilir.","fa":"صفحه را بخوان، چون حتی صفحه‌ی واقعی هم ممکن است چیز دیگری بگوید.","ex":"Is the number there?"}],"phrases":[{"phrase":"According to the AI answer, X. I found this in Y. I could not confirm Z.","meaning":{"en":"A note to copy.","tr":"Kopyalanacak not.","fa":"یادداشت برای کپی."},"copy":true}]},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Saying how sure you are","tr":"Ne kadar emin olduğunu söylemek","fa":"بگو چقدر مطمئنی"},"steps":[{"en":"According to + source gives the source, not your view.","tr":"According to + kaynak, görüşünü değil kaynağı söyler.","fa":"با ⁨according to⁩ نام منبع را می‌گویی، نه نظر خودت را.","ex":"According to the AI answer, it lasts two years."},{"en":"As far as I can tell shows your limit.","tr":"As far as I can tell sınırını gösterir.","fa":"با ⁨As far as I can tell⁩ نشان می‌دهی تا کجا مطمئنی.","ex":"As far as I can tell, it is correct."}],"table":{"headers":{"en":["How sure","Pattern","Example"],"tr":["Ne kadar emin","Kalıp","Örnek"],"fa":["چقدر مطمئن","الگو","مثال"]},"rows":[["sure","I found this in","I found this in the datasheet."],["partly","It seems that","It seems that the price went up."],["not sure","I could not confirm","I could not confirm the date."]]},"wrong":"This is 100% true because the AI said it.","right":"This seems to be true, but I still need to check the source."}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Check a claim","tr":"Bir iddiayı kontrol et","fa":"یک ادعا را بررسی کن"},"item":"AI answer: \"LED lamps last exactly 37,000 hours, according to a 2024 study. [1]\"","answer":"According to the AI answer, the lamps last 37,000 hours. I opened source 1, a seller's page. It says \"up to 50,000 hours\". I could not confirm the 2024 study.","walk":[{"en":"Open the number.","tr":"Numarayı aç.","fa":"لینک شماره‌دار را باز کن."},{"en":"Compare the page with the claim.","tr":"Sayfayı iddiayla karşılaştır.","fa":"صفحه را با ادعا مقایسه کن."},{"en":"Report what you found and what you didn't.","tr":"Neyi bulduğunu ve bulamadığını aktar.","fa":"بگو چه چیزی را پیدا کردی و چه چیزی را نه."}],"why":{"en":"The answer sounds exact, but the page says something else and the study can't be found. Your note separates what you found from what you didn't, so nobody uses a guess as a fact.","tr":"Yanıt kesin görünür, ama sayfa başka bir şey söyler ve çalışma bulunamaz. Notun bulduğunla bulamadığını ayırır, böylece kimse tahmini gerçek diye kullanmaz.","fa":"جواب دقیق به نظر می‌رسد، ولی صفحه چیز دیگری می‌گوید و تحقیق پیدا نمی‌شود. یادداشت تو چیزی را که پیدا کردی از چیزی که پیدا نکردی جدا می‌کند، پس کسی حدس را به‌جای واقعیت به کار نمی‌برد."},"cut":["exactly 37,000 hours","a 2024 study"],"cutHint":{"en":"Tap the claims you can't use until you check them.","tr":"Kontrol etmeden kullanamayacağın iddialara dokun.","fa":"روی ادعاهایی بزن که تا بررسی‌شان نکنی نمی‌توانی از آن‌ها استفاده کنی."}},"quick":{"prompt":"Perplexity's answer has numbered links. What can still be wrong?","options":["Its sentence may not match the page","The numbers only show how sure it is","Nothing, because the links prove it"],"correct":0,"why":{"en":"Its sentence may not match the page: it still writes likely words about those pages. Open the number and check; a link alone doesn't prove the answer.","tr":"Its sentence may not match the page: o sayfalar hakkında yine olası kelimeler yazar. Numarayı açıp kontrol et; bağlantı tek başına yanıtı kanıtlamaz.","fa":"جواب ⁨Its sentence may not match the page⁩ است، چون باز هم درباره‌ی آن صفحه‌ها کلمه‌های محتمل می‌نویسد. شماره را باز کن و بررسی کن؛ لینک به‌تنهایی جواب را ثابت نمی‌کند."},"point":1,"hint2":{"en":"It searches first, then writes. Which part does the tool write itself, in its own likely words?","tr":"Önce arar, sonra yazar. Hangi kısmı kendi olası kelimeleriyle kendisi yazar?","fa":"اول جست‌وجو می‌کند، بعد می‌نویسد. کدام بخش را خودش با کلمه‌های محتمل خودش می‌نویسد؟"}},"quickAfter":3,"remember":{"en":"A link doesn't prove an answer, so open it and see if the page really says that. You can now check an AI answer's claims and write a note on what you confirmed.","tr":"Bağlantı yanıtı kanıtlamaz; aç ve sayfanın gerçekten bunu söyleyip söylemediğine bak. Artık bir yapay zekâ yanıtının iddialarını kontrol edebilir ve neyi doğruladığını not edebilirsin.","fa":"لینک داشتن به معنای درست بودن جواب نیست؛ پس بازش کن و ببین صفحه واقعاً همین را می‌گوید یا نه. حالا می‌توانی ادعاهای جواب هوش مصنوعی را بررسی کنی و یادداشتی درباره‌ی چیزهای تأییدشده بنویسی."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر ⁨B2⁩"},"head":{"en":"Careful verbs: appears to, is said to, there is no evidence that","tr":"Dikkatli fiiller: appears to, is said to, there is no evidence that","fa":"فعل‌های محتاطانه: ⁨appears to⁩، ⁨is said to⁩، ⁨there is no evidence that⁩"},"steps":[{"en":"Appears to is careful: it may not be true.","tr":"appears to dikkatli bir ifadedir: doğru olmayabilir.","fa":"با ⁨appears to⁩ محتاطانه حرف می‌زنی، چون شاید درست نباشد.","ex":"The page appears to be old."},{"en":"There is no evidence that means you looked and found none.","tr":"there is no evidence that, bakıp bulamadığını söyler.","fa":"⁨there is no evidence that⁩ یعنی گشتی و پیدا نکردی.","ex":"There is no evidence that this is true."}],"table":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["appears to + verb","This study appears to be invented."],["there is no evidence that","There is no evidence that it lasts longer."]]},"body":{"en":"B2: write your note with appears to and there is no evidence that.","tr":"B2: Notunu appears to ve there is no evidence that ile yaz.","fa":"⁨B2⁩: یادداشتت را با ⁨appears to⁩ و ⁨there is no evidence that⁩ بنویس."}},"tool":"perplexity"}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
